def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_power_12(n):
    if n == 1:
        # n = 1. n^12 = 1. tau(1) = 1. Condition: 1 = 1.
        return 1

    factors = prime_factorization(n)

    # n = p1^a1 * p2^a2 * ...
    # n^12 = p1^(12*a1) * p2^(12*a2) * ...
    # tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...

    tau_val = 1
    for exponent in factors.values():
        tau_val *= (12 * exponent + 1)
    return tau_val

# Test cases
results = []
for n in range(1, 101):
