def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def solve():
    solutions = []
    # Try combinations of a_i. 
    # Max value of a_i: 
    # 2^a > 12a+1. 
    # a=1: 2 > 13 (F)
    # a=2: 4 > 25 (F)
    # a=3: 8 > 37 (F)
    # a=4: 16 > 49 (F)
    # a=5: 32 > 61 (F)
    # a=6: 64 > 73 (F)
    # a=7: 128 > 85 (T)
    # a=8: 256 > 97 (T)
    # So a_i can only be small. Let's try a_i up to 10.

    # k=1
    for a1 in range(1, 11):
        n = 12 * a1 + 1
        factors = get_prime_factorization(n)
        if len(factors) == 1:
            p, exp = list(factors.items())[0]
            if exp == a1:
                solutions.append(n)

    # k=2
    for a1 in range(1, 11):
        for a2 in range(a1, 11):
            n = (12 * a1 + 1) * (12 * a2 + 1)
            factors = get_prime_factorization(n)
            if len(factors) == 2:
                exps = sorted(factors.values())
                target_exps = sorted([a1, a2])
                if exps == target_exps:
                    solutions.append(n)

    # k=3
    for a1 in range(1, 11):
        for a2 in range(a1, 11):
            for a3 in range(a2, 11):
                n = (12 * a1 + 1) * (12 * a2 + 1) * (12 * a3 + 1)
                factors = get_prime_factorization(n)
                if len(factors) == 3:
                    exps = sorted(factors.values())
                    target_exps = sorted([a1, a2, a3])
                    if exps == target_exps:
                        solutions.append(n)

    # k=4
    for a1 in range(1, 11):
        for a2 in range(a1, 11):
            for a3 in range(a2, 11):
                for a4 in range(a3, 11):
                    n = (12 * a1 + 1) * (12 * a2 + 1) * (12 * a3 + 1) * (12 * a4 + 1)
                    factors = get_prime_factorization(n)
                    if len(factors) == 4:
                        exps = sorted(factors.values())
                        target_exps = sorted([a1, a2, a3, a4])
                        if exps == target_exps:
                            solutions.append(n)

    return sorted(list(set(solutions)))

